protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: Cosmos DB throws at startup in EF Core 9.
    // Manage indexing via the container's indexing policy (Azure Portal / Bicep).
    modelBuilder.Entity<Product>().ToContainer("Products");

    // Preserve EF Core 8 discriminator property name ("Discriminator")
    // so existing 500K documents remain queryable. EF Core 9 defaults to "$type".
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // Preserve EF Core 8 compound id format ("Product|123") so existing
    // documents are accessible via FindAsync / point-reads.
    // EF Core 9 defaults to key-only ids (e.g. "123").
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

